fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();
    
    // If the input array is empty or has only one element, return it unchanged
    if n == 0 || n == 1 {
        return numbers;
    }
    
    // Create a new vector with the required size
    let mut result = Vec::with_capacity(2 * n - 1);
    
    // Iterate through the input array and fill the result vector
    for i in 0..n {
        result.push(numbers[i]); // Add the current element
        if i < n - 1 { // Avoid adding delimiter after the last element
            result.push(delimiter); // Add the delimiter
        }
    }
    
    result
}